// Every request must get an answer. An uncaught throw here would leave the
// webhook hanging and look to the caller like a dead endpoint, so the whole
// handler is wrapped: anything unexpected becomes a readable 500 instead.

try {
  // Single entry point for both apps. One URL, routed on whether the body
  // carries an `action`:
  //
  //   no action  -> a booking submitted from the Inkheaven website form
  //   action     -> an Inkdesk request (list, dashboard, reschedule, ...)
  //
  // Storage is the workflow's own static data, so there is no database and no
  // credential to configure. See README.md for the trade-off and the
  // file-backed alternative.

  const incoming = $input.first().json ?? {};
  const raw = incoming.body ?? incoming;

  // inkdesk sends text/plain to dodge a CORS preflight, so n8n hands the body
  // over as a string rather than a parsed object.
  let body = raw;
  if (typeof raw === 'string') {
    const text = raw.trim();
    if (text) {
      try {
        body = JSON.parse(text);
      } catch {
        return [{ json: { status: 400, body: { ok: false, error: 'bad_request', message: 'Body was not valid JSON.' } } }];
      }
    } else {
      body = {};
    }
  }
  if (!body || typeof body !== 'object' || Array.isArray(body)) body = {};

  // ------------------------------------------------------------------ helpers

  const pad = (n) => String(n).padStart(2, '0');

  const dayISO = (offset = 0) => {
    const d = new Date();
    d.setDate(d.getDate() + offset);
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  };

  const stampNow = () => {
    const d = new Date();
    return `${dayISO(0)}T${pad(d.getHours())}:${pad(d.getMinutes())}:00`;
  };

  // Inkheaven sends date as dd-mm-yyyy; Inkdesk compares against yyyy-mm-dd.
  const toISODate = (v) => {
    const s = String(v == null ? '' : v).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    const m = /^(\d{2})-(\d{2})-(\d{4})$/.exec(s);
    return m ? `${m[3]}-${m[2]}-${m[1]}` : null;
  };

  const str = (v, max = 2000) =>
    String(v == null ? '' : v).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);

  const clone = (v) => JSON.parse(JSON.stringify(v));

  const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const ALL_STATUSES = ['new', 'confirmed', 'rescheduled', 'completed', 'cancelled'];
  const ACTIVE_STATUSES = ['new', 'confirmed', 'rescheduled'];

  // ------------------------------------------------------------------- store

  const store = $getWorkflowStaticData('global');
  if (!store.appointments) store.appointments = {};
  if (!store.blockedDates) store.blockedDates = [];
  if (!store.seq) store.seq = 1;

  const data = store.appointments;
  const blockedDates = store.blockedDates;

  const all = () => Object.values(data);
  const bySessionAsc = (a, b) => (a.date === b.date ? (a.time < b.time ? -1 : 1) : a.date < b.date ? -1 : 1);

  const applyScope = (items, scope) => {
    const today = dayISO(0);
    const out = items.slice();
    if (scope === 'upcoming') {
      return out.filter((a) => ACTIVE_STATUSES.includes(a.status) && a.date >= today).sort(bySessionAsc);
    }
    if (scope === 'today') {
      return out.filter((a) => a.date === today && a.status !== 'cancelled').sort(bySessionAsc);
    }
    if (scope === 'past') {
      return out
        .filter((a) => a.date < today || ['completed', 'cancelled'].includes(a.status))
        .sort((a, b) => bySessionAsc(b, a));
    }
    return out.sort((a, b) => bySessionAsc(b, a));
  };

  const reply = (body, status) => [{ json: { status, body } }];
  const ok = (data) => reply({ ok: true, data }, 200);
  const fail = (error, message, fields) => {
    const status = error === 'notfound' ? 404 : error === 'auth' ? 401 : 400;
    const payload = { ok: false, error, message };
    if (fields) payload.fields = fields;
    return reply(payload, status);
  };

  const nextId = () => {
    const id = 'APT-' + String(store.seq).padStart(4, '0');
    store.seq += 1;
    return id;
  };

  // ------------------------------------------------- intake: website booking

  // No `action` means the Inkheaven booking form. The proxy already sanitised
  // this, but the workflow can also be hit directly, so re-check.
  if (!body.action) {
    // Honeypot: a bot filled it in. Report success, store nothing.
    if (body.company) return ok({ received: true });

    const fields = {};
    const name = str(body.name, 120);
    const email = str(body.email, 200);
    const phone = str(body.phone, 40);
    const description = str(body.description, 4000);

    if (!name) fields.name = 'Name is required.';
    if (!email) fields.email = 'Email is required.';
    else if (!EMAIL_RE.test(email)) fields.email = 'Enter a valid email address.';
    if (!phone) fields.phone = 'Phone is required.';
    if (!description) fields.description = 'Tell us about the tattoo.';
    if (Object.keys(fields).length) return fail('validation', 'Please check the highlighted fields.', fields);

    const now = stampNow();
    const record = {
      id: nextId(),
      created_at: now,
      name,
      email: email.toLowerCase(),
      phone,
      style: str(body.style, 40) || 'other',
      placement: str(body.placement, 40),
      size: str(body.size, 40),
      description,
      date: toISODate(body.dateIso) || toISODate(body.date) || dayISO(0),
      time: str(body.time, 5) || '12:00',
      budget: str(body.budget, 40),
      status: 'new',
      admin_notes: '',
      updated_at: now,
      source: 'website',
    };

    data[record.id] = record;
    return ok(clone(record));
  }

  // ------------------------------------------------------------ inkdesk: api

  const action = String(body.action || '').trim();
  const params = body.params && typeof body.params === 'object' ? body.params : {};

  switch (action) {
    // Settings > Test connection.
    case 'ping':
      return ok({ service: 'inkdesk-api (n8n)', version: 1 });

    case 'list': {
      let items = all();
      const status = String(params.status || 'all');
      const q = String(params.q || '').trim().toLowerCase();

      if (status !== 'all') items = items.filter((a) => a.status === status);
      if (q) {
        items = items.filter((a) =>
          `${a.name} ${a.email} ${a.phone} ${a.id}`.toLowerCase().includes(q),
        );
      }
      return ok({ items: applyScope(items, String(params.scope || 'upcoming')) });
    }

    case 'clientHistory': {
      const q = String(params.q || '').trim().toLowerCase();
      if (!q) return fail('validation', 'A phone or email is required.');

      const matches = all().filter(
        (a) => String(a.phone).toLowerCase() === q || String(a.email).toLowerCase() === q,
      );
      matches.sort((a, b) => bySessionAsc(b, a));

      const first = matches[0] || null;
      return ok({
        items: clone(matches),
        count: matches.length,
        client: first ? { name: first.name, phone: first.phone, email: first.email } : null,
      });
    }

    case 'dashboard': {
      const today = dayISO(0);
      const items = all();
      const counts = { all: items.length, new: 0, confirmed: 0, rescheduled: 0, completed: 0, cancelled: 0 };

      items.forEach((a) => {
        if (counts[a.status] != null) counts[a.status] += 1;
      });

      const upcomingItems = items
        .filter((a) => ACTIVE_STATUSES.includes(a.status) && a.date >= today)
        .sort(bySessionAsc);
      const weekEnd = dayISO(6);

      return ok({
        counts,
        today: items.filter((a) => a.date === today && !['cancelled', 'completed'].includes(a.status)).length,
        week: upcomingItems.filter((a) => a.date <= weekEnd).length,
        upcoming: upcomingItems.length,
      });
    }

    case 'meta':
      return ok({ blockedDates: clone(blockedDates) });

    case 'updateStatus': {
      const appointment = data[String(body.id || '')];
      if (!appointment) return fail('notfound', 'Appointment not found.');

      const status = String(body.status || '').toLowerCase();
      if (!ALL_STATUSES.includes(status)) return fail('validation', 'Unknown status.');

      appointment.status = status;
      appointment.updated_at = stampNow();
      return ok(clone(appointment));
    }

    case 'reschedule': {
      const appointment = data[String(body.id || '')];
      if (!appointment) return fail('notfound', 'Appointment not found.');

      const payload = body.payload && typeof body.payload === 'object' ? body.payload : {};
      const date = toISODate(payload.date);
      if (!date) return fail('validation', 'A valid date is required.');

      appointment.date = date;
      appointment.time = str(payload.time, 5) || appointment.time || '12:00';
      appointment.status = 'rescheduled';
      appointment.updated_at = stampNow();
      return ok(clone(appointment));
    }

    case 'saveNotes': {
      const appointment = data[String(body.id || '')];
      if (!appointment) return fail('notfound', 'Appointment not found.');

      appointment.admin_notes = str(body.notes, 2000);
      appointment.updated_at = stampNow();
      return ok(clone(appointment));
    }

    case 'addManual': {
      const payload = body.payload && typeof body.payload === 'object' ? body.payload : {};

      const fields = {};
      const name = str(payload.name, 120);
      const email = str(payload.email, 200);
      const phone = str(payload.phone, 40);
      if (!name) fields.name = 'Name is required.';
      if (!email) fields.email = 'Email is required.';
      if (!phone) fields.phone = 'Phone is required.';
      if (Object.keys(fields).length) return fail('validation', 'Please check the highlighted fields.', fields);

      const now = stampNow();
      const appointment = {
        id: nextId(),
        created_at: now,
        name,
        email: email.toLowerCase(),
        phone,
        style: str(payload.style, 40) || 'other',
        placement: str(payload.placement, 40),
        size: str(payload.size, 40),
        description: str(payload.description, 4000),
        date: toISODate(payload.date) || dayISO(0),
        time: str(payload.time, 5) || '12:00',
        budget: str(payload.budget, 40),
        status: 'confirmed',
        admin_notes: '',
        updated_at: now,
        source: 'manual',
      };

      data[appointment.id] = appointment;
      return ok(clone(appointment));
    }

    case 'deleteAppointment': {
      const id = String(body.id || '');
      if (!data[id]) return fail('notfound', 'Appointment not found.');
      delete data[id];
      return ok({ id });
    }

    case 'blockDate': {
      const payload = body.payload && typeof body.payload === 'object' ? body.payload : {};
      const date = toISODate(payload.date);
      if (!date) return fail('validation', 'A valid date is required.');

      const existing = blockedDates.find((b) => b.date === date);
      if (existing) existing.reason = str(payload.reason, 200);
      else blockedDates.push({ date, reason: str(payload.reason, 200) });

      return ok({ date });
    }

    case 'unblockDate': {
      const payload = body.payload && typeof body.payload === 'object' ? body.payload : {};
      const date = toISODate(payload.date);
      const index = blockedDates.findIndex((b) => b.date === date);
      if (index !== -1) blockedDates.splice(index, 1);
      return ok({ date });
    }

    default:
      return fail('bad_request', 'Unknown action: ' + action);
  }

} catch (err) {
  return [
    {
      json: {
        status: 500,
        body: {
          ok: false,
          error: 'server',
          message: 'Could not process the request.',
        },
      },
    },
  ];
}
